// Generates src/api/schema.d.ts from the committed OpenAPI document (frontend/openapi.json); no running API needed.
// The backend build regenerates openapi.json; run this after it changes (npm run gen:api).
import { writeFile } from 'node:fs/promises'
import openapiTS, { astToString } from 'openapi-typescript'

const input = new URL('../openapi.json', import.meta.url)
const output = new URL('../src/api/schema.d.ts', import.meta.url)

const header = `/**
 * Generated by "npm run gen:api" from frontend/openapi.json.
 * Do not edit by hand: run the command again when the API changes.
 */

`

const ast = await openapiTS(input)
await writeFile(output, header + astToString(ast))

console.log('schema.d.ts generated from openapi.json')
